SELECT t.id, t.user_id AS userId, t.topic_name AS topicName, t.parent_id AS parentId, t.sort_order AS sortOrder, t.create_time AS createTime, t.update_time AS updateTime, IFNULL(n.note_count, 0) AS noteCount FROM biz_topic t LEFT JOIN ( SELECT topic_id, COUNT(1) AS note_count FROM biz_note WHERE status != 8 GROUP BY topic_id ) n ON t.id = n.topic_id WHERE t.user_id = #{userId}
